  C -- no --> D{"user config.json names out?"}
  D -- yes --> X
  D -- no --> E{"a local clone whose parent is not inside a repo?"}
  E -- yes --> F["beside the clone: code-review / repo"]
  E -- no --> G["user folder: reviews / host / owner / repo"]
